const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name] || icons.file}"/></svg>`;
const btn = (label, action, extra = '', kind = '') => `<button type="button" class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;
const tag = (label, kind = '') => `<span class="tag ${kind}">${label}</span>`;
const mascot = '../mascot/static/verity.jpeg';
const routes = [['home','Home','home'],['study','Study Studio','study'],['practice','Practice','practice'],['progress','Progress','progress'],['opportunities','Opportunities','opportunities'],['portfolio','Portfolio','portfolio'],['connections','Connections','connections'],['map','Concept map','map']];
const subjects = [
 {id:'physics',name:'Physics',topic:'Forces & motion',color:'blue',materials:8,score:60},
 {id:'maths',name:'Mathematics',topic:'Linear equations',color:'purple',materials:12,score:80},
 {id:'chemistry',name:'Chemistry',topic:'Particles & reactions',color:'green',materials:6,score:70},
 {id:'biology',name:'Biology',topic:'Circulation',color:'',materials:7,score:50},
 {id:'english',name:'English',topic:'Building an argument',color:'purple',materials:5,score:70},
 {id:'design',name:'Design & Technology',topic:'Design process',color:'green',materials:4,score:80}
];
const lessons = {
 physics:{title:'Let’s make forces click.',source:'Forces & motion · class notes',page:'p. 4',opening:'A 2 kg trolley has a net force of 8 N to the right. Before calculating, what do you think happens to its motion?',quote:'The net force on an object equals its mass multiplied by its acceleration: Fnet = ma. Acceleration is in the direction of the net force.',steps:['Start with the object: a trolley.','Label the mass: 2 kg.','Add the net force: 8 N to the right.','Use a = Fnet ÷ m. The acceleration is 4 m/s² to the right.'],prompt:'Which quantity are we trying to find?',hint:'Look for the mass and the net force. Which operation rearranges Fnet = ma to make a the subject?',topicRows:[['Forces & motion',6,10],['Moments',10,10],['Light',2,10]]},
 maths:{title:'One step closer to x.',source:'Linear equations · class notes',page:'p. 2',opening:'We have 2x + 4 = 12. What can we do to both sides to start isolating x?',quote:'An equation stays balanced when the same operation is applied to both sides.',steps:['Start with 2x + 4 = 12.','Subtract 4 from both sides.','This gives 2x = 8.','Divide both sides by 2: x = 4.'],prompt:'What operation undoes adding 4?',hint:'Keep both sides balanced. Try subtracting 4 from both sides before dividing.',topicRows:[['Linear equations',8,10],['Graphs',7,10],['Geometry',9,10]]},
 chemistry:{title:'Follow the particles.',source:'Particles & reactions · class notes',page:'p. 3',opening:'When ice melts, are its water molecules replaced by a new substance, or does their arrangement change?',quote:'A physical change changes the state or arrangement of particles without forming a new substance.',steps:['Start with solid ice.','Add thermal energy.','The particles become able to move past one another.','Liquid water forms; the substance is still H₂O.'],prompt:'What stays the same during melting?',hint:'Think about the identity of the substance before and after the change.',topicRows:[['Particles & reactions',7,10],['Atomic structure',6,10],['Acids & bases',8,10]]},
 biology:{title:'Trace the journey.',source:'Circulation · class notes',page:'p. 5',opening:'Blood travels from the right side of the heart to the lungs. What does it gain there?',quote:'At the lungs, blood gains oxygen and releases carbon dioxide. It returns to the left side of the heart before being pumped to the body.',steps:['Start at the right side of the heart.','Blood travels to the lungs.','Oxygenated blood returns to the left side of the heart.','Blood is pumped to the body, then returns to the right side.'],prompt:'Why does blood visit the lungs?',hint:'Consider the gas that body cells need for aerobic respiration.',topicRows:[['Circulation',5,10],['Cells',7,10],['Nutrition',6,10]]},
 english:{title:'Give your argument shape.',source:'Persuasive writing · class notes',page:'p. 2',opening:'Your claim is “School gardens are useful.” What evidence would help a reader judge that claim?',quote:'Support a claim with relevant evidence, then explain how the evidence supports your reasoning.',steps:['State a clear claim.','Add relevant evidence.','Explain the link between evidence and claim.','Consider a reasonable counterargument.'],prompt:'What evidence could support this claim?',hint:'Choose a concrete observation or finding, then explain why it matters.',topicRows:[['Building an argument',7,10],['Comprehension',8,10],['Summary',6,10]]},
 design:{title:'Make room to try.',source:'Design process · class notes',page:'p. 1',opening:'A user finds a bottle hard to grip. What should we understand before drawing a solution?',quote:'Understand the user’s need, create a prototype, test with users, then improve it using what you learn.',steps:['Understand the user and need.','Build a small prototype.','Test it with the intended user.','Use observations to improve the design.'],prompt:'Whose needs are we designing for?',hint:'Ask the user when and why gripping the bottle is difficult.',topicRows:[['Design process',8,10],['Materials',7,10],['Evaluation',6,10]]}
};
const questions = {
 physics:[{q:'A net force of 12 N acts on a 3 kg trolley. What is its acceleration?',options:['4 m/s²','9 m/s²','36 m/s²'],answer:0,why:'a = Fnet ÷ m = 12 ÷ 3 = 4 m/s².'},{q:'Two horizontal forces act on a box: 10 N right and 4 N left. What is the net force?',options:['14 N right','6 N right','6 N left'],answer:1,why:'Opposing forces subtract: 10 − 4 = 6 N to the right.'},{q:'The same net force acts on two trolleys. Which has greater acceleration?',options:['The heavier trolley','Both always have the same acceleration','The lighter trolley'],answer:2,why:'For the same net force, a = Fnet ÷ m. A smaller mass gives greater acceleration.'}],
 maths:[{q:'Solve 3x + 6 = 18.',options:['x = 4','x = 6','x = 8'],answer:0,why:'Subtract 6 to get 3x = 12, then divide by 3.'},{q:'Which first step preserves the balance of x + 7 = 10?',options:['Subtract 7 from only the left','Subtract 7 from both sides','Divide only the right by 7'],answer:1,why:'Apply the same operation to both sides to preserve equality.'},{q:'Solve 5x = 35.',options:['x = 30','x = 175','x = 7'],answer:2,why:'Divide both sides by 5: x = 35 ÷ 5 = 7.'}],
 chemistry:[{q:'When ice melts, which statement is correct?',options:['It remains water','It becomes oxygen','Its molecules vanish'],answer:0,why:'Melting is a physical change; the substance remains water.'},{q:'Which process forms a new substance?',options:['Melting ice','Burning paper','Cutting paper'],answer:1,why:'Burning is a chemical change that forms new substances.'},{q:'In a liquid, particles can…',options:['Only vibrate in fixed positions','Disappear','Move past one another'],answer:2,why:'Liquid particles remain close but can move past one another.'}],
 biology:[{q:'What does blood gain in the lungs?',options:['Oxygen','Food particles','Bone cells'],answer:0,why:'Oxygen diffuses into blood at the lungs.'},{q:'Which side of the heart receives oxygenated blood from the lungs?',options:['Right side','Left side','Neither side'],answer:1,why:'Blood from the lungs returns to the left side of the heart.'},{q:'What is the main job of the heart?',options:['Digest food','Make bones','Pump blood'],answer:2,why:'The heart pumps blood through the circulatory system.'}],
 english:[{q:'Which best supports a claim?',options:['Relevant evidence with explanation','Repeating the claim','An unrelated example'],answer:0,why:'Evidence and reasoning let the reader assess the claim.'},{q:'What is a counterargument?',options:['A spelling correction','A reasonable opposing view','A repeated conclusion'],answer:1,why:'A counterargument considers a reasonable opposing position.'},{q:'After giving evidence, what strengthens your paragraph?',options:['Change topic','Add an unrelated quote','Explain how it supports the claim'],answer:2,why:'Explain the connection between evidence and your claim.'}],
 design:[{q:'Before designing a grip aid, what should you do?',options:['Understand the user’s difficulty','Choose the final color','Advertise the solution'],answer:0,why:'Understand the intended user and their needs before choosing a solution.'},{q:'What is a prototype useful for?',options:['Avoiding feedback','Testing an idea','Guaranteeing success'],answer:1,why:'A prototype allows an idea to be tried and tested.'},{q:'What should inform the next version?',options:['Only the designer’s preference','A random guess','Observations from user testing'],answer:2,why:'Use observations from users to guide improvements.'}]
};
const opportunities = [
 {id:'maker',title:'Community maker afternoon',host:'Example community lab',type:'Hands-on',location:'In person',time:'Saturday · 2 hours',free:true,open:true,icon:'design',why:'You chose hands-on projects. No grade-based match is used.',support:'Example offer: materials provided; transport support needs organiser confirmation.',description:'Try a small assistive-design challenge with a mentor. Bring curiosity; a finished portfolio is not required.'},
 {id:'industry',title:'A day behind the design',host:'Example industry partner',type:'Industry exposure',location:'Online',time:'After class · 60 minutes',free:true,open:true,icon:'portfolio',why:'You chose design and technology as an interest.',support:'Example offer: remote attendance and captions; device access still needs checking.',description:'Meet a product designer, see a project in progress, and ask what their working day is like.'},
 {id:'pathways',title:'Pathways, without the guesswork',host:'Example guidance team',type:'Career guidance',location:'Online',time:'Flexible booking · 30 minutes',free:true,open:true,icon:'map',why:'You asked to explore several education and work pathways.',support:'Example offer: first-time guidance and a preparation checklist.',description:'A short conversation about your interests, constraints, and possible next steps across education pathways.'},
 {id:'robotics',title:'Weekend robotics taster',host:'Example enrichment provider',type:'Enrichment',location:'In person',time:'Saturday · 4 hours',free:false,open:false,icon:'physics',why:'Related to your interest in making things; eligibility is not yet clear.',support:'Example listing: $20 fee; fee assistance and access details unconfirmed.',description:'Explore sensors and simple programming. Institution restrictions must be clarified before applying.'}
];
const defaults = () => ({subject:'physics',exam:60,notes:{},saved:[],entries:[],results:[],connected:false,uploadName:'',interests:['Hands-on','Design'],support:[],opFilter:'all',freeOnly:false,openOnly:false,location:'all'});
let state = defaults();
try {const old=JSON.parse(localStorage.getItem(KEY)||'null');if(old && typeof old==='object')state={...state,...old};} catch {}
if(!subjects.some(s=>s.id===state.subject)) state.subject='physics';
for(const key of ['saved','entries','results','interests','support'])if(!Array.isArray(state[key]))state[key]=[];
let page='home', boardMode='board', boardStep=2, boardLabel='Trolley', messages=[], quiz=null, scoreMode='separate', opportunitySearch='', toastTimer;
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('Browser storage unavailable. Changes remain in this session.');}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function syncSidebar(){const hidden=matchMedia('(max-width:700px)').matches&&!$('.sidebar').classList.contains('open');$('.sidebar').inert=hidden;$('.sidebar').setAttribute('aria-hidden',String(hidden));}
const sub = () => subjects.find(s=>s.id===state.subject);
const lesson = () => lessons[state.subject];
const practiceScore = () => {const last=state.results.filter(r=>r.subject===state.subject).at(-1);return last?Math.round(last.correct/last.total*100):sub().score;};
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;}
function selectSubjects(){return `<select id="subject-select" aria-label="Subject">${subjects.map(s=>`<option value="${s.id}" ${state.subject===s.id?'selected':''}>${s.name}</option>`).join('')}</select>`;}
function render(){
 const route=routes.find(r=>r[0]===page)||routes[0];
 $('#nav').innerHTML=routes.map((r,i)=>`${i===6?'<div class="nav-separator"></div>':''}<a class="nav-link ${page===r[0]?'active':''}" href="#${r[0]}" ${page===r[0]?'aria-current="page"':''}>${icon(r[2])}${r[1]}</a>`).join('');
 $('#crumb').textContent=route[1]==='Home'?'Overview':route[1];
 $('#main').innerHTML=({home:homeView,study:studyView,practice:practiceView,progress:progressView,opportunities:opportunitiesView,portfolio:portfolioView,connections:connectionsView,map:mapView}[page]||homeView)();
 document.title=`Verity — ${route[1]}`;
}
function navigate(to){if(!routes.some(r=>r[0]===to))to='home';if($('#dialog').open)$('#dialog').close();if(location.hash===`#${to}`){page=to;render();}else location.hash=to;$('.sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');syncSidebar();}
function homeView(){return `${heading('A little progress. A lot of possibility.','Welcome back, Alex. What would you like to make clearer today?',btn(`${icon('connections')}Your materials`,'navigate','data-to="connections"'))}
 <section class="hero" aria-label="Continue learning"><div><div class="hero-tag">${icon('light')}Your next small step</div><h2>Big ideas start with<br>a little “oh, I get it.”</h2><p>Pick up where you left off in Physics. Let’s work through forces together, one step at a time.</p><div class="hero-bottom">${btn(`Let’s figure it out ${icon('arrow')}`,'study-subject','data-subject="physics"','dark')}<span>Forces & motion · about 10 min</span></div></div><img class="mascot" src="${mascot}" alt="Verity, your round golden study companion"></section>
 <div class="home-grid"><section><div class="section-top"><div><h2>Your classroom, a little clearer.</h2><p>Same class materials. Your own pace.</p></div><button class="text-button" data-action="subjects">All subjects ${icon('arrow')}</button></div><div class="subject-grid">${subjects.slice(0,4).map(s=>`<button class="subject-card" data-action="study-subject" data-subject="${s.id}"><div class="subject-top"><span class="subject-icon ${s.color}">${icon(s.id)}</span>${tag(s.id==='physics'?'Pick up here':'Class materials',s.id==='physics'?'gold':'')}</div><h3>${s.name}</h3><p>${s.topic}</p><div class="sub-footer"><span>${s.materials} sample resources</span><strong>Open studio ↗</strong></div></button>`).join('')}</div></section>
 <aside class="home-aside"><section class="panel"><div class="section-top"><h2>A plan for today</h2>${tag('Suggested','gold')}</div><ol class="steps-list"><li><span class="step-dot active">1</span><div><h3>Understand the tricky bit</h3><p>Explore forces on the whiteboard.</p><button class="text-button" data-action="study-subject" data-subject="physics">Open your lesson →</button></div></li><li><span class="step-dot">2</span><div><h3>Try it on your own</h3><p>Three questions. Room to learn.</p><button class="text-button" data-action="navigate" data-to="practice">Start a quick check →</button></div></li><li><span class="step-dot">3</span><div><h3>See what’s becoming clearer</h3><p>Your evidence, topic by topic.</p><button class="text-button" data-action="navigate" data-to="progress">View your progress →</button></div></li></ol></section>
 <section class="panel"><div class="tag-row">${tag('Beyond the classroom','green')}${tag('Proposed')}</div><div class="mini-opportunity" style="border:0;padding-top:0"><h3>There’s more than one way forward.</h3><p>Explore experiences by interest, access needs, and eligibility. Your grades aren’t the whole story.</p><button class="text-button" data-action="navigate" data-to="opportunities">Find your next possibility ${icon('arrow')}</button></div></section></aside></div>`;}

function diagram(){
 const step=boardStep;
 if(state.subject==='physics')return `<svg class="diagram" viewBox="0 0 620 320" role="img" aria-label="Step ${step+1}: ${escapeHTML(lesson().steps[step])}"><defs><marker id="arrowhead" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0 8 4 0 8" fill="#315b8d"/></marker></defs><text x="310" y="38" text-anchor="middle" font-size="17" font-weight="600">What makes the trolley accelerate?</text><path d="M72 248H550" stroke="#b7b6ac" stroke-width="2"/><rect x="175" y="151" width="187" height="76" rx="10" fill="#fff3cb" stroke="#c79b32" stroke-width="2"/><circle cx="210" cy="239" r="11" fill="#fff" stroke="#797768" stroke-width="2"/><circle cx="325" cy="239" r="11" fill="#fff" stroke="#797768" stroke-width="2"/><text x="267" y="184" text-anchor="middle" font-size="16">${escapeHTML(boardLabel)}</text>${step>=1?'<text x="267" y="209" text-anchor="middle" font-size="18" font-weight="600">m = 2 kg</text>':''}${step>=2?'<path d="M369 186h139" stroke="#315b8d" stroke-width="3" marker-end="url(#arrowhead)"/><text x="438" y="166" text-anchor="middle" font-size="16">Fnet = 8 N</text>':''}${step>=3?'<text x="308" y="98" text-anchor="middle" font-size="25" font-weight="600">a = Fnet / m = 4 m/s² →</text>':''}<text x="310" y="290" text-anchor="middle" font-size="12">Horizontal net force shown · diagram not to scale</text></svg>`;
 if(state.subject==='maths'){const lines=['2x + 4 = 12','2x + 4 − 4 = 12 − 4','2x = 8','x = 4'];return `<svg class="diagram" viewBox="0 0 620 320" role="img" aria-label="${escapeHTML(lesson().steps[step])}">${lines.slice(0,step+1).map((line,i)=>`<text x="310" y="${62+i*66}" text-anchor="middle" font-size="${i===step?30:23}" font-weight="${i===step?650:400}">${line}</text>`).join('')}</svg>`;}
 const nodes={chemistry:['Solid ice','Add energy','Particles move','Liquid water'],biology:['Right heart','Lungs','Left heart','Body'],english:['Claim','Evidence','Explanation','Counterargument'],design:['Understand','Prototype','Test','Improve']}[state.subject];
 return `<svg class="diagram" viewBox="0 0 620 320" role="img" aria-label="${escapeHTML(lesson().steps.slice(0,step+1).join(' '))}"><defs><marker id="flowhead" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7" fill="#797768"/></marker></defs>${nodes.slice(0,step+1).map((n,i)=>{const x=i%2?345:95,y=i<2?58:205;return `${i===1?'<path d="M265 90h65" stroke="#797768" stroke-width="2" marker-end="url(#flowhead)"/>':i===2?'<path d="M430 125v38H180v27" fill="none" stroke="#797768" stroke-width="2" marker-end="url(#flowhead)"/>':i===3?'<path d="M265 237h65" stroke="#797768" stroke-width="2" marker-end="url(#flowhead)"/>':''}<rect x="${x}" y="${y}" width="170" height="64" rx="9" fill="${i===step?'#fff0bd':'#f5f5f3'}" stroke="#c1bcad"/><text x="${x+85}" y="${y+38}" text-anchor="middle" font-size="16">${n}</text>`;}).join('')}${state.subject==='biology'&&step===3?'<path d="M516 237h40V27H180v24" fill="none" stroke="#797768" stroke-width="1.5" marker-end="url(#flowhead)"/>':''}</svg>`;
}
function boardContent(){if(boardMode==='materials')return `<div class="source-content"><span class="tag blue">Sample resource · ${lesson().page}</span><h3 class="mt">${lesson().source}</h3><p>This example extract stands in for a teacher-provided resource. No Classroom file has been imported.</p><blockquote>${lesson().quote}</blockquote><p class="muted">In the product, explanations would link to the exact selected document and page. Missing or conflicting source material should be surfaced.</p>${btn('Return to whiteboard','board-mode','data-mode="board"','small')}</div>`;
 if(boardMode==='notes')return `<form class="notes-content" id="notes-form"><label class="field">In your own words<textarea name="notes" placeholder="What clicked? What would you still like to ask?">${escapeHTML(state.notes[state.subject]||'')}</textarea></label>${btn(`${icon('check')}Save note`,'save-notes','','primary small')}<p class="hint-note">Saved in this browser only.</p></form>`;
 return `<div class="board-area">${diagram()}<p class="board-step">${lesson().steps[boardStep]}</p></div><div class="board-controls">${btn(`${icon('back')}Back`,'board-prev',boardStep===0?'disabled':'','small')}<span class="board-counter">Step ${boardStep+1} of 4</span>${btn(boardStep===3?`${icon('replay')}Start again`:`Next step ${icon('arrow')}`,boardStep===3?'board-reset':'board-next','','small primary')}</div>`;}
function studyView(){return `${heading(lesson().title,'Your class materials, a whiteboard, and space to ask why.',btn(`Try it yourself ${icon('arrow')}`,'navigate','data-to="practice"','primary'))}<div class="toolbar">${selectSubjects()}${tag(sub().topic,'blue')}<span class="spacer"></span><div class="segmented" aria-label="Study view">${[['board','Whiteboard'],['materials','Class materials'],['notes','My notes']].map(([key,label])=>`<button aria-pressed="${boardMode===key}" data-action="board-mode" data-mode="${key}">${label}</button>`).join('')}</div></div>
 <div class="studio-grid"><section class="board-pane"><div class="pane-header"><div><h2>${boardMode==='materials'?'The source behind this lesson':boardMode==='notes'?'Make it your own':'Let’s see how it works'}</h2><p>${boardMode==='board'?'Step-through diagram · sample explanation':sub().name}</p></div>${boardMode==='board'&&state.subject==='physics'?`<button class="icon-button" data-action="edit-label" aria-label="Edit diagram label">${icon('edit')}</button>`:''}</div>${boardContent()}</section>
 <aside class="tutor-pane"><div class="pane-header"><div class="tutor-header"><img src="${mascot}" alt=""><div><h2>Verity</h2><p>Your study companion</p></div></div>${tag('Demo tutor','gold')}</div><div class="messages" aria-live="polite"><div class="chat-bubble"><strong>Let’s work it out together.</strong>${lesson().opening}<div class="chat-source">${icon('file')}Sample class notes · ${lesson().page}</div></div>${messages.map(m=>`<div class="chat-bubble ${m.role==='user'?'user':''}">${escapeHTML(m.text)}</div>`).join('')}</div><div class="chat-compose"><div class="chat-chips"><button data-action="hint">Give me a hint</button><button data-action="show-source">Show me the source</button><button data-action="board-next">Explain the next step</button></div><form id="chat-form"><input name="message" aria-label="Message Verity" placeholder="Ask about this lesson…" maxlength="600" required autocomplete="off"><button class="button primary" type="submit" aria-label="Send message">${icon('send')}</button></form><p class="hint-note">Scripted replies for this preview. Your message stays in this tab.</p></div></aside></div><div class="evidence-strip"><span>${icon('file').replace('class="icon"','class="icon" style="display:inline-block;width:12px;height:12px;vertical-align:middle"')} <strong>Source:</strong> ${lesson().source}</span><span><strong>Practice:</strong> ${practiceScore()}% ${state.results.some(r=>r.subject===state.subject)?'latest preview attempt':'sample baseline'}</span><span><strong>Session goal:</strong> explain it, then try it independently.</span></div>`;}

function practiceView(){if(quiz?.finished)return resultView();if(quiz)return attemptView();return `${heading('A small check. A clearer next step.','Practise from a topic, then see what needs another look.')}<div class="two-col"><section class="panel"><div class="section-top"><h2>Build your practice</h2>${tag('Sample quiz','gold')}</div><form id="quiz-setup" class="form-stack"><label class="field">Subject${selectSubjects()}</label><label class="field">Topic<select name="topic"><option>${sub().topic}</option></select></label><div class="stats-top" style="margin-bottom:0"><div><span class="stat-label">Question count</span><p class="copy muted">3 questions</p></div><div><span class="stat-label">Approximate time</span><p class="copy muted">3–5 minutes</p></div></div><div class="info-note">Try each question independently first. Review the explanation after each attempt; a missed question becomes a useful next step.</div><label class="check-row"><input type="checkbox" checked disabled>Based on this topic’s sample class notes</label><button class="button primary" type="submit">Start practice ${icon('arrow')}</button><p class="hint-note">Fixed example questions. No quiz is generated or sent to a teacher.</p></form></section><aside class="panel"><h2>Make mistakes useful.</h2><ol class="steps-list"><li><span class="step-dot">1</span><div><h3>Have a go</h3><p>Choose an answer before seeing the explanation.</p></div></li><li><span class="step-dot">2</span><div><h3>Find the missing link</h3><p>See the reasoning behind each answer.</p></div></li><li><span class="step-dot">3</span><div><h3>Choose what comes next</h3><p>Return to your board or save the attempt to Progress.</p></div></li></ol><div class="placeholder mt">${icon('image')}<strong>Mascot pose placeholder</strong><span>Verity encouraging a first attempt</span></div></aside></div>`;}
function attemptView(){const q=questions[quiz.subject][quiz.index];return `${heading('Give it a go.','An attempt tells us where to start.',btn('Leave practice','leave-quiz'))}<section class="panel quiz-card"><div class="section-top">${tag(`${subjects.find(s=>s.id===quiz.subject).name} · ${lessons[quiz.subject].topicRows[0][0]}`,'blue')}<span class="muted">${quiz.index+1} / 3</span></div><div class="quiz-progress" aria-label="Question ${quiz.index+1} of 3">${[0,1,2].map(i=>`<span class="${i<=quiz.index?'done':''}"></span>`).join('')}</div><form id="answer-form"><fieldset style="border:0;padding:0;margin:0"><legend class="quiz-question">${q.q}</legend>${q.options.map((o,i)=>`<label class="quiz-option"><input type="radio" name="answer" value="${i}" ${quiz.selected===i?'checked':''} ${quiz.checked?'disabled':''} required><span>${o}</span></label>`).join('')}</fieldset>${quiz.checked?`<div class="quiz-feedback ${quiz.selected===q.answer?'':'incorrect'}"><strong>${quiz.selected===q.answer?'That’s right.':'A useful thing to revisit.'}</strong><p>${q.why}</p></div>`:''}<div class="quiz-actions"><span class="hint-note">Independent attempt · sample questions</span>${quiz.checked?btn(quiz.index===2?'See my results':'Next question →','quiz-next','','primary'):'<button class="button primary" type="submit">Check my answer</button>'}</div></form></section>`;}
function resultView(){const correct=quiz.answers.filter((a,i)=>a===questions[quiz.subject][i].answer).length;return `${heading('Now you know where to go next.','One practice attempt is a snapshot, not a label.')}<div class="two-col"><section class="panel"><span class="tag green">Practice complete · saved locally</span><div class="result-score">${correct}<span class="muted" style="font-size:26px"> / 3</span></div><p class="copy muted">${correct===3?'All three clicked this time. A later question in a new context would give stronger evidence.':'Review the reasoning below, then revisit the topic on your whiteboard.'}</p><div class="feature-list mt">${questions[quiz.subject].map((q,i)=>`<div class="feature-row"><div><strong>Question ${i+1}</strong><p class="hint-note">${q.why}</p></div>${tag(quiz.answers[i]===q.answer?'Correct':'Revisit',quiz.answers[i]===q.answer?'green':'gold')}</div>`).join('')}</div><div class="quiz-actions">${btn('Back to the whiteboard','navigate','data-to="study"')}${btn(`View progress ${icon('arrow')}`,'navigate','data-to="progress"','primary')}</div></section><aside class="panel"><h2>Keep the evidence honest.</h2><p class="copy muted mt">This records first answers in this preview. Exam results remain separate. Repeating these same questions measures familiarity too.</p><div class="placeholder mt">${icon('image')}<strong>Mascot pose placeholder</strong><span>Verity celebrating effort, not ranking students</span></div>${btn('Return to practice setup','quiz-reset','','wide mt')}</aside></div>`;}

function radar(){const values=subjects.map(s=>{const last=state.results.filter(r=>r.subject===s.id).at(-1);return last?last.correct/last.total:s.score/100;});const point=(i,r)=>[160+Math.sin(i*Math.PI/3)*r,145-Math.cos(i*Math.PI/3)*r];const pts=r=>subjects.map((s,i)=>point(i,r).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 320 300" role="img" aria-label="Practice overview: ${subjects.map((s,i)=>`${s.name} ${Math.round(values[i]*100)} percent`).join(', ')}">${[30,60,90].map(r=>`<polygon points="${pts(r)}" fill="none" stroke="#deded5"/>`).join('')}${subjects.map((s,i)=>`<path d="M160 145 ${point(i,90).join(' ')}" stroke="#deded5"/>`).join('')}<polygon points="${values.map((v,i)=>point(i,v*90).join(',')).join(' ')}" fill="#f0b526" fill-opacity=".22" stroke="#a87413" stroke-width="2"/>${subjects.map((s,i)=>{const [x,y]=point(i,120);return `<text x="${x}" y="${y}" text-anchor="middle" dominant-baseline="middle">${s.id==='design'?'D&T':s.name==='Mathematics'?'Maths':s.name}</text>`;}).join('')}</svg>`;}
function progressView(){const last=state.results.filter(r=>r.subject===state.subject).at(-1);const rows=lesson().topicRows;const score=practiceScore();const exam=state.subject==='physics'?Number(state.exam):null;const combined=exam===null?null:Math.round(score*(scoreMode==='70/30'?.7:.5)+exam*(scoreMode==='70/30'?.3:.5));return `${heading('Progress you can actually see.','Follow the topic, the attempt, and the evidence behind it.',btn(`${icon('edit')}Add an exam result`,'exam'))}<div class="toolbar">${selectSubjects()}${tag('Sample records + your preview attempts')}<span class="spacer"></span><button class="text-button" data-action="score-help">How scores work</button></div><div class="two-col"><div><section class="panel"><div class="section-top"><h2>${sub().name}, topic by topic</h2>${tag('Practice evidence','gold')}</div><div class="stats-top"><div class="stat-block"><span class="stat-label">${last?'Latest preview practice':'Sample practice snapshot'}</span><strong>${score}%</strong><p>${last?`${last.correct} of ${last.total} · ${new Date(last.date).toLocaleDateString('en-SG')}`:'Illustrative baseline, not a measured ability'}</p></div><div class="stat-block"><span class="stat-label">Exam result</span><strong>${exam===null?'—':`${exam}%`}</strong><p>${exam===null?'No exam entered for this subject':'Physics · manually entered · unverified'}</p></div></div><div class="table-wrap"><table><thead><tr><th>Topic</th><th>Practice</th><th>Evidence</th><th>Next step</th></tr></thead><tbody>${rows.map(([topic,got,total],i)=>`<tr><td><strong>${topic}</strong></td><td><div class="score-row"><span>${i===0&&last?`${last.correct}/${last.total}`:`${got}/${total}`}</span><span class="progress-bar"><span style="width:${i===0&&last?score:got/total*100}%"></span></span></div></td><td>${tag(i===0&&last?'Preview attempt':'Sample record',i===0&&last?'green':'')}</td><td><button class="text-button" data-action="${i===0?'start-topic':'future-topic'}" data-topic="${escapeHTML(topic)}">${i===0?'Practise →':'Preview →'}</button></td></tr>`).join('')}</tbody></table></div><p class="hint-note mt">Question difficulty and sample size differ. A higher score does not establish a stronger capability across subjects.</p></section><section class="panel"><h2>Explore the two score formulas</h2><p class="copy muted mt">Your notes propose both 50/50 and 70/30. Compare them here; separate evidence is the provisional default.</p><div class="segmented mt" aria-label="Score presentation">${[['separate','Keep separate'],['50/50','50% quiz / 50% exam'],['70/30','70% quiz / 30% exam']].map(([value,label])=>`<button aria-pressed="${scoreMode===value}" data-action="score-mode" data-mode="${value}">${label}</button>`).join('')}</div><div class="score-comparison"><p class="copy muted">${scoreMode==='separate'?'Two sources, each with its own limitations.':combined===null?'Add an exam result for Physics to preview this formula.':'Illustrative blended score. This is not a validated mastery measure.'}</p><strong>${scoreMode==='separate'?'—':combined===null?'—':`${combined}%`}</strong></div></section></div><aside><section class="panel"><div class="section-top"><h2>The wider picture</h2>${tag('Practice only')}</div>${radar()}<p class="radar-legend">Subject snapshot · inspect evidence below</p><div class="feature-list mt">${subjects.map(s=>`<button class="text-button feature-row" style="width:100%" data-action="progress-subject" data-subject="${s.id}"><span>${s.name}</span><span>${state.results.some(r=>r.subject===s.id)?'Preview attempt':'Sample baseline'} ↗</span></button>`).join('')}</div></section><section class="panel"><h3>A score is one piece of the story.</h3><p class="copy muted mt">Projects, responsibilities, and experiences can show things a quiz cannot.</p><button class="text-button mt" data-action="navigate" data-to="portfolio">Build your evidence collection ${icon('arrow')}</button></section></aside></div>`;}

function opportunitiesView(){const list=opportunities.filter(o=>(state.opFilter!=='saved'||state.saved.includes(o.id))&&(!state.freeOnly||o.free)&&(!state.openOnly||o.open)&&(state.location==='all'||o.location===state.location)&&(`${o.title} ${o.type} ${o.description}`.toLowerCase().includes(opportunitySearch.toLowerCase())));return `${heading('More doors. Your kind of next step.','Explore experiences across pathways, with the practical details up front.',btn(`${icon('settings')}My interests & support`,'preferences'))}<div class="notice-row"><div class="tag-row">${tag('Proposed access-focused direction','gold')}${tag('All listings are fictional examples')}</div><span class="saved-count">${state.saved.length} saved</span></div><div class="filter-bar"><input type="search" id="op-search" placeholder="Search interests or experiences…" aria-label="Search opportunities" value="${escapeHTML(opportunitySearch)}"><select id="op-location" aria-label="Opportunity format"><option value="all">Any format</option><option ${state.location==='Online'?'selected':''}>Online</option><option ${state.location==='In person'?'selected':''}>In person</option></select><label class="check-row"><input type="checkbox" id="free-only" ${state.freeOnly?'checked':''}>No programme fee</label><label class="check-row"><input type="checkbox" id="open-only" ${state.openOnly?'checked':''}>All institutions stated</label></div><div class="toolbar"><div class="segmented" aria-label="Opportunity list"><button data-action="op-filter" data-filter="all" aria-pressed="${state.opFilter==='all'}">Explore</button><button data-action="op-filter" data-filter="saved" aria-pressed="${state.opFilter==='saved'}">Saved (${state.saved.length})</button></div><span class="spacer"></span><span class="muted" style="font-size:11px">${list.length} example${list.length===1?'':'s'} · no score-based ranking</span></div><div class="two-col" style="grid-template-columns:minmax(0,1fr)"><section class="panel">${list.length?list.map(o=>`<article class="opportunity"><div class="opportunity-art">${icon(o.icon)}<span>Image slot</span></div><div><div class="tag-row">${tag(o.type,'blue')}${tag(o.free?'No programme fee':'$20 example fee',o.free?'green':'gold')}${tag(o.open?'All institutions stated':'Eligibility unclear',o.open?'green':'gold')}</div><h3>${o.title}</h3><p>${o.host} · fictional listing</p><p>${o.description}</p><div class="opportunity-meta"><span>${o.location}</span><span>${o.time}</span></div><p><strong>Access detail:</strong> ${o.support}</p></div><div class="opportunity-buttons">${btn(`${icon('bookmark')}${state.saved.includes(o.id)?'Saved':'Save'}`,'save-op',`data-id="${o.id}" aria-pressed="${state.saved.includes(o.id)}"`,'small')}${btn(`See the details ${icon('arrow')}`,'op-detail',`data-id="${o.id}"`,'small primary')}</div></article>`).join(''):`<div class="empty-state">${icon('opportunities')}<h2>${state.opFilter==='saved'?'No saved matches yet.':'No matching examples.'}</h2><p>Try changing a filter, or explore the full example list.</p>${btn('Clear filters','clear-filters','','primary')}</div>`}</section></div><div class="idea-comparison"><section class="panel"><h3>“Free” isn’t the whole access story.</h3><p>Travel, equipment, timing, caring duties, accessibility, and application confidence can still stand in the way.</p><button class="text-button" data-action="support-plan">Make a support checklist →</button></section><section class="panel"><h3>Your potential needs room to show.</h3><p>Bring a project, a responsibility, a reflection, or an example of helping someone. You choose what to share.</p><button class="text-button" data-action="navigate" data-to="portfolio">Collect your evidence →</button></section></div>`;}

function portfolioView(){return `${heading('There’s more to you than a result.','Collect concrete examples of what you’ve tried, learned, and contributed.',btn(`${icon('plus')}Add an experience`,'add-entry','','primary'))}<div class="two-col"><section class="panel"><div class="section-top"><h2>My evidence collection</h2>${tag('Private · this browser','green')}</div><article class="portfolio-entry"><div class="timeline-marker">${icon('design')}</div><div><div class="tag-row">${tag('Example entry')}${tag('Self-reported')}</div><h3 class="mt">Made a bottle easier to grip</h3><p>Built a cardboard grip prototype, asked a classmate to test it, and changed the shape using their feedback.</p><div class="tag-row">${tag('Design iteration','blue')}${tag('Listening','green')}</div><p><strong>Evidence:</strong> prototype photo and a short reflection would go here. No attachment or reviewer is verified in this preview.</p><button class="text-button" data-action="entry-detail">View example evidence →</button></div></article>${state.entries.map(e=>`<article class="portfolio-entry"><div class="timeline-marker">${icon('file')}</div><div><div class="tag-row">${tag('Your preview entry','gold')}${tag('Self-reported')}</div><h3 class="mt">${escapeHTML(e.title)}</h3><p>${escapeHTML(e.description)}</p><p><strong>Evidence reference:</strong> ${escapeHTML(e.evidence||'Not added yet')}</p><p class="hint-note">Saved locally · no external reviewer</p></div></article>`).join('')}<div class="info-note mt">Character is not an AI score. A specific action and its context are more useful than a label such as “resilient” or “high potential.”</div></section><aside><section class="panel"><h2>What can count?</h2><div class="feature-list mt"><div class="feature-row">A project you improved ${icon('design')}</div><div class="feature-row">A responsibility you sustained ${icon('clock')}</div><div class="feature-row">A contribution to your community ${icon('opportunities')}</div><div class="feature-row">A reflection on something difficult ${icon('study')}</div></div><p class="copy muted mt">Paid competitions and prestigious activities shouldn’t be the only route to evidence.</p></section><section class="panel"><div class="placeholder">${icon('image')}<strong>Mascot pose placeholder</strong><span>Verity holding a collection of your work</span></div><button class="text-button mt" data-action="share-preview">Preview student-controlled sharing →</button></section></aside></div>`;}

function connectionsView(){return `${heading('Your materials. Clear boundaries.','Choose what comes in and see where it is used.')}<div class="two-col"><section class="panel"><h2>Learning sources</h2><div class="connector"><div class="connector-logo">${icon('study')}</div><div class="connector-copy"><h3>Google Classroom</h3><p>Selected classes and materials for study context.</p><span class="connection-state">${state.connected?'Connected in simulation · no Google account used':'Not connected · sample resources available'}</span></div>${btn(state.connected?'Disconnect demo':'Simulate connection','connect','','small')}</div><div class="connector"><div class="connector-logo">${icon('file')}</div><div class="connector-copy"><h3>Upload a class resource</h3><p>${state.uploadName?escapeHTML(state.uploadName):'Preview a file selection when Classroom is unavailable.'}</p><span class="hint-note">Filename only. File contents are not read or uploaded.</span></div><label class="button small" for="resource-file">Choose file</label><input id="resource-file" type="file" accept=".pdf,.docx,.txt,.png,.jpg" style="position:absolute;width:1px;height:1px;opacity:0"><button class="text-button" data-action="upload-help">Details</button></div><div class="connector"><div class="connector-logo">${icon('progress')}</div><div class="connector-copy"><h3>Exam results</h3><p>Manual entry, clearly marked as self-reported.</p></div>${btn('Enter result','exam','','small')}</div><div class="connector"><div class="connector-logo">${icon('opportunities')}</div><div class="connector-copy"><h3>Opportunity providers</h3><p>Curated examples now. Organiser-fed, checked listings are a future proposal.</p></div>${btn('View examples','navigate','data-to="opportunities"','small')}</div></section><aside><section class="panel"><h2>A source should stay a source.</h2><div class="copy muted mt"><p>Keep class boundaries visible. Show the resource and page behind an explanation.</p><p>Show missing access, stale materials, and unsupported claims explicitly.</p><p>Do not send private reflections or practical support needs to an organiser by default.</p></div><div class="subtle-line"></div><div class="feature-list"><div class="feature-row"><span>AI tutor service</span>${tag('Not connected')}</div><div class="feature-row"><span>Diagram renderer</span>${tag('Local examples','gold')}</div><div class="feature-row"><span>Accounts & storage</span>${tag('Browser only')}</div></div></section><section class="panel"><h3>Try a source error state</h3><p class="copy muted mt">See how a blocked or unavailable class resource could be explained.</p>${btn('Preview unavailable source','source-error','','small mt')}</section></aside></div>`;}

function flowNode(to,title,desc,primary=false){return `<button class="map-node ${primary?'primary':''}" data-action="navigate" data-to="${to}">${icon(to)}<strong>${title}</strong><small>${desc}</small></button>`;}
function mapView(){return `${heading('The whole idea, connected.','A working conversation starter. Every direction here is still open.',btn('View challenge','challenge','','primary'))}<section class="panel"><div class="section-top"><h2>Your base concept</h2>${tag('From DOCX + workshop photos')}</div><p class="copy muted">Tap a stage to explore its screen. These connectors show intended relationships; services are not integrated.</p><div class="map-flow">${flowNode('connections','Class materials','Selected course context')}<span class="map-arrow">→</span>${flowNode('study','Learn together','Tutor + visual whiteboard',true)}<span class="map-arrow">→</span>${flowNode('practice','Try independently','Topical questions')}<span class="map-arrow">→</span>${flowNode('progress','See progress','Topics + exam records')}</div><div class="map-flow" style="padding-top:0">${flowNode('progress','Learning evidence','Scores with limitations')}<span class="map-arrow">→</span>${flowNode('opportunities','Explore pathways','Experiences + guidance')}<span class="map-arrow">→</span>${flowNode('portfolio','Keep a record','Work + reflections')}</div></section><div class="idea-comparison"><section class="panel"><div class="tag-row">${tag('Recommended direction','green')}${tag('Proposal')}</div><h2 class="mt">Access first. Learning as support.</h2><p>For Challenge 4, lead with a student finding an eligible experience and getting the support to actually take part.</p><ul><li>Start from interests and constraints.</li><li>Show eligibility, cost, timing, and missing details.</li><li>Help prepare capability evidence and an application.</li><li>Offer a human support route when a barrier remains.</li></ul><button class="text-button" data-action="navigate" data-to="opportunities">Explore this direction →</button></section><section class="panel"><div class="tag-row">${tag('Alternative direction')}${tag('Proposal')}</div><h2 class="mt">An opportunity bridge for organisers.</h2><p>Help providers remove unnecessary institution and grade filters, offer accessible tasters, and review concrete evidence.</p><ul><li>Potentially addresses exclusion at its source.</li><li>Requires organiser partners and changed processes.</li><li>Harder to demonstrate without provider participation.</li></ul><button class="text-button" data-action="organiser">See proposed organiser flow →</button></section></div><section class="panel mt"><h2>What’s here, and what’s still a question</h2><div class="table-wrap mt"><table><thead><tr><th>Area</th><th>Origin</th><th>Preview boundary</th></tr></thead><tbody><tr><td>Subject tutor, board, quizzes, stats</td><td>DOCX + photos</td><td>Scripted lessons and sample evidence</td></tr><tr><td>Career opportunities and records</td><td>Photo 2</td><td>Fictional listings, local entries</td></tr><tr><td>50/50 vs 70/30 score weights</td><td>Conflicting DOCX notes</td><td>Both explorable; neither validated</td></tr><tr><td>Access filters and support checklist</td><td>Proposed for Challenge 4</td><td>Local controls, no provider confirmation</td></tr><tr><td>Verified evidence and organiser handoff</td><td>Future proposal</td><td>No verification or external sharing</td></tr></tbody></table></div></section>`;}

function openDialog(title,body,actions=''){const dialog=$('#dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-button" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!dialog.open)dialog.showModal();}
function preferences(){openDialog('What would make this work for you?',`<p>Proposed student-controlled preferences. Used only in this browser preview; not sent to organisers.</p><form id="preferences-form" class="form-stack"><fieldset style="border:0;padding:0"><legend class="field mb">Interests</legend>${['Hands-on','Design','Technology','People & community'].map(x=>`<label class="check-row"><input name="interests" type="checkbox" value="${x}" ${state.interests.includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset><fieldset style="border:0;padding:0"><legend class="field mb">Support I may want</legend>${['Transport or fees','Device or internet access','Flexible timing','Application guidance','Accessibility arrangements'].map(x=>`<label class="check-row"><input name="support" type="checkbox" value="${x}" ${state.support.includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset><p class="hint-note">These preferences inform the example support checklist. They do not generate a live match or reveal sensitive details to a provider.</p><button class="button primary" type="submit">Save my preferences</button></form>`);}
function supportPlan(op){const needs=state.support.length?state.support:['Transport or fees','Flexible timing','Application guidance'];openDialog('Make the next step possible',`<p>${op?`For <strong>${op.title}</strong>. `:''}A proposed support checklist. No support has been arranged.</p><div class="stack mt">${needs.map(x=>`<label class="check-row"><input type="checkbox">${escapeHTML(x)}: identify what to ask for</label>`).join('')}<label class="check-row"><input type="checkbox">Confirm eligibility and actual availability</label><label class="check-row"><input type="checkbox">Choose what evidence to share</label><label class="check-row"><input type="checkbox">Identify a trusted person who can help</label></div><div class="info-note mt">A checklist alone does not remove a barrier. The product would need a real organiser, adviser, or support partner who can respond.</div>`,btn('Edit support preferences','preferences')+btn('Keep exploring','close-dialog','','primary'));}

document.addEventListener('click',event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;
 switch(action){
 case 'navigate':navigate(el.dataset.to);break;
 case 'menu':{const open=$('.sidebar').classList.toggle('open');$('.mobile-menu').setAttribute('aria-expanded',String(open));syncSidebar();break;}
 case 'skip':event.preventDefault();$('#main').focus();$('#main').scrollIntoView();break;
 case 'close-dialog':$('#dialog').close();break;
 case 'subjects':openDialog('Choose your classroom',`<div class="stack">${subjects.map(s=>btn(`${icon(s.id)}${s.name}`,'choose-subject',`data-subject="${s.id}"`)).join('')}</div>`);break;
 case 'choose-subject':$('#dialog').close();
 case 'study-subject':state.subject=el.dataset.subject;boardStep=0;messages=[];quiz=null;persist();navigate('study');break;
 case 'progress-subject':state.subject=el.dataset.subject;persist();render();break;
 case 'board-mode':boardMode=el.dataset.mode;render();break;
 case 'board-prev':boardStep=Math.max(0,boardStep-1);render();break;
 case 'board-next':boardStep=Math.min(3,boardStep+1);boardMode='board';render();break;
 case 'board-reset':boardStep=0;render();break;
 case 'hint':messages.push({role:'assistant',text:lesson().hint});render();break;
 case 'show-source':boardMode='materials';render();break;
 case 'edit-label':openDialog('Edit this diagram label',`<p>Try the editable-shape idea. This preview supports one label; a production whiteboard would need full shape editing.</p><form id="label-form" class="form-stack"><label class="field">Object label<input name="label" value="${escapeHTML(boardLabel)}" maxlength="18" required></label><button class="button primary" type="submit">Update diagram</button></form>`);break;
 case 'save-notes':{event.preventDefault();const form=$('#notes-form');state.notes[state.subject]=form.elements.notes.value;persist();toast('Note saved in this browser.');break;}
 case 'leave-quiz':openDialog('Leave this attempt?',`<p>This unfinished attempt will not be saved. Completed attempts remain in Progress.</p>`,btn('Keep practising','close-dialog')+btn('Leave attempt','confirm-leave','','primary'));break;
 case 'confirm-leave':$('#dialog').close();quiz=null;render();break;
 case 'quiz-next':if(!quiz?.checked)break;if(quiz.index<2){quiz.index++;quiz.checked=false;quiz.selected=null;}else{quiz.finished=true;const correct=quiz.answers.filter((a,i)=>a===questions[quiz.subject][i].answer).length;state.results.push({subject:quiz.subject,correct,total:3,date:new Date().toISOString()});persist();}render();break;
 case 'quiz-reset':quiz=null;render();break;
 case 'start-topic':quiz=null;navigate('practice');break;
 case 'future-topic':openDialog(`${escapeHTML(el.dataset.topic)} practice`, `<p>This topic appears in your broader tracking idea. The complete interactive sample uses <strong>${sub().topic}</strong>.</p><p>A future version would select the matching class material and create a fresh topical quiz.</p>`,btn('Try available sample','start-topic','','primary'));break;
 case 'score-mode':scoreMode=el.dataset.mode;render();break;
 case 'score-help':openDialog('What does this score mean?',`<p>Practice and exam results are different evidence sources. The DOCX specifies 50/50 in one section and 70/30 in another.</p><p>For this preview, separate evidence is the default. The comparison controls show both formulas without endorsing either. The calculation uses the displayed whole-number percentages and rounds the final result.</p><p>Baseline subject values and historical topic records are illustrative. A completed preview quiz adds your first-answer result. Repeated sample questions are not a valid long-term learning measure.</p>`);break;
 case 'exam':openDialog('Add a sample exam result',`<p>Manual entry for Physics. This remains self-reported and is not verified against a school record.</p><form id="exam-form" class="form-stack"><label class="field">Physics exam result (%)<input name="exam" type="number" min="0" max="100" step="1" value="${Number(state.exam)}" required></label><button class="button primary" type="submit">Save result locally</button></form>`);break;
 case 'op-filter':state.opFilter=el.dataset.filter;persist();render();break;
 case 'save-op':{const id=el.dataset.id;state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();toast(state.saved.includes(id)?'Example saved to your list.':'Example removed from saved.');break;}
 case 'clear-filters':state.freeOnly=false;state.openOnly=false;state.location='all';state.opFilter='all';opportunitySearch='';persist();render();break;
 case 'op-detail':{const o=opportunities.find(x=>x.id===el.dataset.id);openDialog(o.title,`${tag('Fictional example · no registration','gold')}<p>${o.description}</p><dl class="detail-list"><div><dt>Provider</dt><dd>${o.host}</dd></div><div><dt>Eligibility</dt><dd>${o.open?'Example listing states all institutions. Other criteria still need confirmation.':'Institution and age requirements are unclear. Ask before applying.'}</dd></div><div><dt>Cost</dt><dd>${o.free?'No programme fee in this example. Other costs may remain.':'$20 example fee; assistance unconfirmed.'}</dd></div><div><dt>Format</dt><dd>${o.location} · ${o.time}</dd></div><div><dt>Why explore</dt><dd>This example covers ${o.type.toLowerCase()}. Your current interests: ${escapeHTML(state.interests.join(', ')||'not set')}. It is not a personalised recommendation.</dd></div><div><dt>Support</dt><dd>${o.support}</dd></div><div><dt>Verification</dt><dd>No real provider, availability, eligibility, or support verified.</dd></div></dl>`,btn('Check practical support','support-plan',`data-id="${o.id}"`)+btn('Preview next step','application',`data-id="${o.id}"`,'primary'));break;}
 case 'application':{const o=opportunities.find(x=>x.id===el.dataset.id);openDialog('Before an application',`<p>A proposed preparation flow for <strong>${o.title}</strong>. Nothing is submitted.</p><ol class="copy"><li>Confirm eligibility, dates, and remaining costs.</li><li>Choose relevant evidence and explain your interest.</li><li>Request needed support through a named contact.</li><li>Review exactly what will be shared before sending.</li></ol><div class="info-note mt">An adviser or organiser handoff needs a real partner. This wireframe cannot provide a placement.</div>`,btn('Build my evidence','dialog-portfolio')+btn('Support checklist','support-plan',`data-id="${o.id}"`,'primary'));break;}
 case 'dialog-portfolio':$('#dialog').close();navigate('portfolio');break;
 case 'preferences':preferences();break;
 case 'support-plan':supportPlan(opportunities.find(x=>x.id===el.dataset.id));break;
 case 'add-entry':openDialog('Add something you’ve done',`<form id="entry-form" class="form-stack"><label class="field">Experience or project<input name="title" maxlength="90" placeholder="e.g. Helped organise a community meal" required></label><label class="field">What did you do, and what changed?<textarea name="description" rows="4" maxlength="1500" placeholder="Describe a specific action, the context, and what you learned." required></textarea></label><label class="field">Evidence reference (optional)<input name="evidence" maxlength="200" placeholder="e.g. Project photo, reflection, or someone who observed it"><small>Text reference only. No file upload or person is contacted.</small></label><button class="button primary" type="submit">Save private entry</button></form>`);break;
 case 'entry-detail':openDialog('An example of useful evidence',`<p><strong>Context:</strong> A classmate found a bottle difficult to grip.</p><p><strong>Action:</strong> Built and revised a grip prototype after a small user test.</p><p><strong>Evidence:</strong> Before/after prototype photos and dated observations could support the account.</p><p><strong>Reflection:</strong> “My first version looked comfortable but slipped. I changed the surface after watching the test.”</p><p>This is invented content. No project, character trait, or reviewer is verified.</p>`);break;
 case 'share-preview':openDialog('You decide what leaves this space',`<p>Proposed sharing controls:</p><div class="stack"><label class="check-row"><input type="checkbox">Selected project and reflection</label><label class="check-row"><input type="checkbox">Evidence references</label><label class="check-row"><input type="checkbox">A support request I choose to disclose</label></div><p>Real sharing would need a named recipient, a review screen, and a way to manage access. This preview creates no link and sends nothing.</p>`);break;
 case 'connect':state.connected=!state.connected;persist();render();toast(state.connected?'Connection simulated. No Google account accessed.':'Demo connection removed.');break;
 case 'upload-help':openDialog('File selection placeholder',`<p>Choose a local file to preview its filename in the connection screen. This prototype does not read, parse, store, or upload its contents.</p><p>Classroom and manual upload are alternative proposed routes into the same study workspace.</p>`);break;
 case 'source-error':openDialog('This resource isn’t available yet',`<div class="info-note">Example error: permission to read this class resource is missing.</div><p>In the product, offer a retry, explain the required access, and allow another resource. Do not invent an explanation from an unavailable file.</p>`,btn('Use sample materials','sample-materials','','primary'));break;
 case 'sample-materials':$('#dialog').close();boardMode='materials';navigate('study');break;
 case 'challenge':openDialog('Challenge 4: Equity & Access Across All Pathways',`<p>Quality opportunities such as internships, industry exposure, career guidance, and enrichment remain unequal and skewed toward traditional or high-performing academic tracks.</p><p>Students from vocational schools, private institutions, or less privileged backgrounds may face structural exclusion.</p><p>The desired system identifies and nurtures potential through capability and character, with support for challenges beyond the classroom.</p><p class="hint-note">Paraphrase of the exact challenge supplied by your team in chat.</p>`);break;
 case 'organiser':openDialog('Proposed organiser-side flow',`<ol class="copy"><li>Publish requirements with a reason for each restriction.</li><li>State real costs, access arrangements, and support contacts.</li><li>Accept several forms of capability evidence.</li><li>Have a human review candidates against a transparent rubric.</li><li>Track who can participate and where barriers persist.</li></ol><p>This is a replacement direction to investigate, not an implemented organiser portal. Its main dependency is willing provider partners.</p>`);break;
 case 'reset':openDialog('Reset this preview?',`<p>Clears only this wireframe’s saved attempts, notes, exam edits, entries, preferences, and saved examples in this browser.</p>`,btn('Keep my preview','close-dialog')+btn('Reset demo','confirm-reset','','primary'));break;
 case 'confirm-reset':state=defaults();quiz=null;messages=[];boardStep=2;boardMode='board';boardLabel='Trolley';scoreMode='separate';opportunitySearch='';persist();$('#dialog').close();navigate('home');toast('Preview reset.');break;
 }
});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='subject-select'){state.subject=el.value;boardStep=0;messages=[];quiz=null;persist();render();}if(el.id==='free-only'||el.id==='open-only'||el.id==='op-location'){if(el.id==='free-only')state.freeOnly=el.checked;if(el.id==='open-only')state.openOnly=el.checked;if(el.id==='op-location')state.location=el.value;persist();render();}if(el.id==='resource-file'&&el.files[0]){state.uploadName=el.files[0].name;persist();render();toast('Filename selected. File contents were not read or uploaded.');}});
document.addEventListener('input',event=>{if(event.target.id==='op-search'){const pos=event.target.selectionStart;opportunitySearch=event.target.value;render();$('#op-search').focus();try{$('#op-search').setSelectionRange(pos,pos);}catch{}}});
document.addEventListener('submit',event=>{
 const form=event.target;event.preventDefault();const data=new FormData(form);
 if(form.id==='chat-form'){const text=String(data.get('message')||'').trim();if(!text)return;messages.push({role:'user',text},{role:'assistant',text:`This is a scripted preview, so I can’t evaluate your message. Here’s the next guiding prompt for this lesson: ${lesson().hint}`});render();$('.messages').scrollTop=$('.messages').scrollHeight;}
 if(form.id==='label-form'){boardLabel=String(data.get('label')).trim()||'Trolley';$('#dialog').close();render();}
 if(form.id==='notes-form'){state.notes[state.subject]=String(data.get('notes'));persist();toast('Note saved in this browser.');}
 if(form.id==='quiz-setup'){quiz={subject:state.subject,index:0,selected:null,checked:false,answers:[],finished:false};render();}
 if(form.id==='answer-form'&&quiz&&!quiz.checked){const answer=data.get('answer');if(answer===null)return;quiz.selected=Number(answer);quiz.answers[quiz.index]=quiz.selected;quiz.checked=true;render();}
 if(form.id==='exam-form'){const exam=Number(data.get('exam'));if(!Number.isInteger(exam)||exam<0||exam>100)return;state.exam=exam;state.subject='physics';persist();$('#dialog').close();render();toast('Physics exam result saved locally as self-reported.');}
 if(form.id==='entry-form'){const title=String(data.get('title')).trim(),description=String(data.get('description')).trim();if(!title||!description)return;state.entries.push({title,description,evidence:String(data.get('evidence')).trim()});persist();$('#dialog').close();render();toast('Private preview entry saved.');}
 if(form.id==='preferences-form'){state.interests=data.getAll('interests');state.support=data.getAll('support');persist();$('#dialog').close();render();toast('Preferences saved locally. No live matching performed.');}
});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);page=routes.some(r=>r[0]===next)?next:'home';$('.sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');syncSidebar();render();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});});
window.addEventListener('resize',syncSidebar);
document.addEventListener('keydown',event=>{if(event.key==='Escape'){$('.sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');syncSidebar();}});
page=routes.some(r=>r[0]===location.hash.slice(1))?location.hash.slice(1):'home';render();syncSidebar();
